//#region src/lib/deserializer/internal/shouldDeserializeNode.ts
const isNodeTypeAllowed = (type, { allowedNodes, disallowedNodes }) => {
	if (allowedNodes && disallowedNodes && allowedNodes.length > 0 && disallowedNodes.length > 0) throw new Error("Cannot combine allowedNodes with disallowedNodes");
	return allowedNodes ? allowedNodes.includes(type) : !disallowedNodes?.includes(type);
};
const shouldDeserializeNode = (node, options) => {
	if (!node.type) return true;
	const type = mdastToPlate(options.editor, node.type);
	if (!isNodeTypeAllowed(type, options)) return false;
	if (options.allowNode?.deserialize) return options.allowNode.deserialize({
		...node,
		type
	});
	return true;
};

