import { KEYS, bindFirst, createSlatePlugin } from "platejs";

//#region src/lib/transforms/insertCallout.ts
const CALLOUT_STORAGE_KEY = "plate-storage-callout";
const insertCallout = (editor, { icon, variant, ...options } = {}) => {
	editor.tf.insertNodes({
		children: [{ text: "" }],
		icon: icon ?? localStorage.getItem(CALLOUT_STORAGE_KEY) ?? "💡",
		type: editor.getType(KEYS.callout),
		variant
	}, options);
};

//#endregion
//#region src/lib/BaseCalloutPlugin.ts
const BaseCalloutPlugin = createSlatePlugin({
	key: KEYS.callout,
	node: { isElement: true },
	rules: {
		break: {
			default: "lineBreak",
			empty: "reset",
			emptyLineEnd: "deleteExit"
		},
		delete: { start: "reset" }
	}
}).extendEditorTransforms(({ editor }) => ({ insert: { callout: bindFirst(insertCallout, editor) } }));

//#endregion
export { CALLOUT_STORAGE_KEY as n, insertCallout as r, BaseCalloutPlugin as t };